+#include <nanobind/nanobind.h>
+
+#include <algorithm>
+#include <cmath>
+#include <cstring>
+#include <stdexcept>
+#include <string>
+#include <tuple>
+
+#include "metal_common.h"
+#include "mlx/allocator.h"
+#include "mlx/array.h"
+#include "mlx/backend/metal/device.h"
